INSERT INTO documents (
  document_type_id, title, reference_year, description, status, visibility,
  source_type, source_url, original_filename, mime_type, file_size_bytes,
  drive_file_id, drive_parent_id, drive_path, drive_created_at,
  drive_modified_at, drive_owner_name, drive_owner_email,
  historical_uploader_name, historical_uploader_email, source_access_level,
  integrity_hash_status, duplicate_review_status, imported_at
)
SELECT type.id, source.original_filename, source.reference_year,
       'Registro importado do acervo legado do Google Drive; classificação documental pendente de conferência humana.',
       'draft', 'internal', 'google_drive', source.source_url,
       source.original_filename, source.mime_type, source.file_size_bytes,
       source.drive_file_id, source.drive_parent_id, source.drive_path,
       source.drive_created_at, source.drive_modified_at,
       source.drive_owner_name, source.drive_owner_email,
       NULL, NULL, source.source_access_level, 'pending',
       source.duplicate_review_status, now()
FROM source
LEFT JOIN document_types type ON type.name = source.type_name
ON CONFLICT (drive_file_id) WHERE drive_file_id IS NOT NULL DO UPDATE SET
  source_url = EXCLUDED.source_url,
  original_filename = EXCLUDED.original_filename,
  mime_type = EXCLUDED.mime_type,
  file_size_bytes = EXCLUDED.file_size_bytes,
  drive_parent_id = EXCLUDED.drive_parent_id,
  drive_path = EXCLUDED.drive_path,
  drive_created_at = EXCLUDED.drive_created_at,
  drive_modified_at = EXCLUDED.drive_modified_at,
  drive_owner_name = EXCLUDED.drive_owner_name,
  drive_owner_email = EXCLUDED.drive_owner_email,
  source_access_level = EXCLUDED.source_access_level,
  duplicate_review_status = CASE
    WHEN documents.duplicate_review_status IN ('confirmed_duplicate', 'not_duplicate', 'unique_hash')
      THEN documents.duplicate_review_status
    ELSE EXCLUDED.duplicate_review_status
  END,
  imported_at = COALESCE(documents.imported_at, EXCLUDED.imported_at),
  updated_at = now();

INSERT INTO audit_logs (entity_type, entity_id, action, details, actor_name, actor_email, actor_role)
SELECT 'document', document.id, 'document_imported_from_drive',
       jsonb_build_object(
         'driveFileId', document.drive_file_id,
         'drivePath', document.drive_path,
         'ownerName', COALESCE(document.drive_owner_name, 'Não identificado'),
         'ownerEmail', COALESCE(document.drive_owner_email, 'Não identificado'),
         'historicalUploader', 'Não identificado',
         'integrityHashStatus', document.integrity_hash_status,
         'duplicateReviewStatus', document.duplicate_review_status
       ),
       'Importação automatizada da Etapa 2', NULL, 'master'
FROM documents document
WHERE document.source_type = 'google_drive'
  AND document.drive_file_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM audit_logs audit
    WHERE audit.entity_type = 'document'
      AND audit.entity_id = document.id
      AND audit.action = 'document_imported_from_drive'
  );

COMMIT;
